import { useState } from "react";
import { Modal, Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import type { StyleProp, TextStyle, ViewStyle } from "react-native";
import { Calendar } from "../calendar/calendar.rn";
import { addDays, startOfDay, startOfMonth } from "../lib/calendar";
import { metrics, useTokens } from "../lib/rn-tokens";

export interface DateRange {
  start: Date;
  end: Date;
}

export interface DateRangePreset {
  label: string;
  range: (today: Date) => DateRange;
}

const defaultPresets: DateRangePreset[] = [
  { label: "Last 7 days", range: (today) => ({ start: addDays(startOfDay(today), -6), end: startOfDay(today) }) },
  { label: "Last 30 days", range: (today) => ({ start: addDays(startOfDay(today), -29), end: startOfDay(today) }) },
  { label: "This month", range: (today) => ({ start: startOfMonth(today), end: startOfDay(today) }) },
];

export interface DateRangePickerProps {
  value?: DateRange | null;
  defaultValue?: DateRange | null;
  onChange?: (range: DateRange) => void;
  label?: string;
  placeholder?: string;
  presets?: DateRangePreset[];
  minDate?: Date;
  maxDate?: Date;
  weekStartsOn?: 0 | 1;
  locale?: string;
  style?: StyleProp<ViewStyle>;
  /** Extend the inner, named parts of the picker: label, trigger, valueText, popover or preset. The React Native counterpart of `classNames`. */
  styles?: {
    label?: StyleProp<TextStyle>;
    trigger?: StyleProp<ViewStyle>;
    valueText?: StyleProp<TextStyle>;
    popover?: StyleProp<ViewStyle>;
    preset?: StyleProp<ViewStyle>;
  };
}

export function DateRangePicker({ value, defaultValue = null, onChange, label = "Date range", placeholder = "Select a range", presets = defaultPresets, minDate, maxDate, weekStartsOn = 0, locale = "en-US", style, styles: parts }: DateRangePickerProps) {
  const tokens = useTokens();
  const [internal, setInternal] = useState<DateRange | null>(defaultValue);
  const [open, setOpen] = useState(false);
  const [anchor, setAnchor] = useState<Date | null>(null);
  const [month, setMonth] = useState(startOfMonth(new Date()));
  const current = value === undefined ? internal : value;
  const short = (date: Date) => date.toLocaleDateString(locale, { month: "short", day: "numeric", year: "numeric" });

  function commit(range: DateRange) {
    if (value === undefined) setInternal(range);
    onChange?.(range);
    setAnchor(null);
    setOpen(false);
  }

  function pick(date: Date) {
    if (!anchor) return setAnchor(date);
    commit(date < anchor ? { start: date, end: anchor } : { start: anchor, end: date });
  }

  return (
    <View style={[local.field, style]}>
      <Text style={[local.label, { color: tokens.foreground }, parts?.label]}>{label}</Text>
      <Pressable
        accessibilityRole="button"
        accessibilityLabel={`${label}${current ? `, ${short(current.start)} to ${short(current.end)}` : ""}`}
        onPress={() => {
          setMonth(startOfMonth(current?.start ?? new Date()));
          setOpen(true);
        }}
        style={[local.trigger, { minHeight: metrics.controlHeight.md, borderColor: tokens.border, backgroundColor: tokens.surface }, parts?.trigger]}
      >
        <Text style={[{ color: current ? tokens.foreground : tokens.textMuted, fontSize: metrics.text.sm }, parts?.valueText]}>{current ? `${short(current.start)} – ${short(current.end)}` : placeholder}</Text>
        <Text style={{ color: tokens.textMuted, fontSize: 14 }}>▾</Text>
      </Pressable>
      <Modal transparent animationType="fade" visible={open} onRequestClose={() => setOpen(false)} statusBarTranslucent>
        <Pressable accessibilityLabel="Close calendar" onPress={() => (setAnchor(null), setOpen(false))} style={local.overlay}>
          <Pressable onPress={() => undefined} style={[local.popover, { borderColor: tokens.border, backgroundColor: tokens.surface }, parts?.popover]}>
            <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ gap: 6, paddingBottom: metrics.space[3] }}>
              {presets.map((preset) => (
                <Pressable key={preset.label} accessibilityRole="button" onPress={() => commit(preset.range(new Date()))} style={[local.preset, { borderColor: tokens.border }, parts?.preset]}>
                  <Text style={{ color: tokens.foreground, fontSize: metrics.text.xs, fontWeight: "500" }}>{preset.label}</Text>
                </Pressable>
              ))}
            </ScrollView>
            <Text style={{ color: tokens.textMuted, fontSize: metrics.text.xs, marginBottom: 4 }}>{anchor ? "Choose the end date" : "Choose the start date"}</Text>
            <Calendar month={month} onMonthChange={setMonth} locale={locale} weekStartsOn={weekStartsOn} minDate={minDate} maxDate={maxDate} range={anchor ? { start: anchor } : (current ?? undefined)} onChange={pick} />
          </Pressable>
        </Pressable>
      </Modal>
    </View>
  );
}

const local = StyleSheet.create({
  field: { alignSelf: "stretch", gap: metrics.space[2] },
  label: { fontSize: metrics.text.sm, fontWeight: "500" },
  trigger: { flexDirection: "row", alignItems: "center", justifyContent: "space-between", paddingHorizontal: metrics.space[3], borderWidth: 1, borderRadius: metrics.radiusControl },
  overlay: { flex: 1, alignItems: "center", justifyContent: "center", padding: metrics.space[5], backgroundColor: "rgba(10, 10, 10, 0.4)" },
  popover: { width: "100%", maxWidth: 360, borderWidth: 1, borderRadius: 26, padding: metrics.space[4] },
  preset: { paddingHorizontal: 12, paddingVertical: 6, borderWidth: 1, borderRadius: 999 },
});

export default DateRangePicker;

import { useColorScheme } from "react-native";

/** The Manicat UI design tokens as React Native values. Same names and meaning as registry/foundation.css. */
export interface ManicatTokens {
  background: string;
  surface: string;
  surfaceMuted: string;
  foreground: string;
  textSecondary: string;
  textMuted: string;
  border: string;
  borderStrong: string;
  accent: string;
  accentStrong: string;
  accentSubtle: string;
  success: string;
  warning: string;
  danger: string;
  controlOn: string;
  controlTrack: string;
  controlThumb: string;
  controlThumbOn: string;
  /** Four distinguishable colours for chart series, the counterpart of --series-1 to --series-4. */
  series: [string, string, string, string];
}

export const lightTokens: ManicatTokens = {
  background: "#ffffff",
  surface: "#ffffff",
  surfaceMuted: "#f6f6f6",
  foreground: "#1b1b1b",
  textSecondary: "#6e6e6e",
  textMuted: "#8f8f8f",
  border: "#ebebeb",
  borderStrong: "#c9c9c9",
  accent: "#4a4a4a",
  accentStrong: "#303030",
  accentSubtle: "rgba(74, 74, 74, 0.1)",
  success: "#1f8a4c",
  warning: "#b8741a",
  danger: "#d03b3b",
  controlOn: "#2c2c2c",
  controlTrack: "#e2e2e2",
  controlThumb: "#ffffff",
  controlThumbOn: "#ffffff",
  series: ["#1f7dcf", "#7128a5", "#e58f00", "#009e84"],
};

export const darkTokens: ManicatTokens = {
  background: "#2b2b2b",
  surface: "#303030",
  surfaceMuted: "#3c3c3c",
  foreground: "#f1f1f1",
  textSecondary: "#c4c4c4",
  textMuted: "#a0a0a0",
  border: "#454545",
  borderStrong: "#5c5c5c",
  accent: "#cfcfcf",
  accentStrong: "#e6e6e6",
  accentSubtle: "rgba(207, 207, 207, 0.13)",
  success: "#5fd48a",
  warning: "#f0b95c",
  danger: "#ff8a80",
  controlOn: "#ececec",
  controlTrack: "#515151",
  controlThumb: "#f4f4f4",
  controlThumbOn: "#2b2b2b",
  series: ["#55adff", "#9c37be", "#e66e00", "#00a861"],
};

/** Shape and rhythm shared by every component, in density-independent pixels. */
export const metrics = {
  radiusControl: 18,
  radiusPill: 9999,
  controlHeight: { sm: 36, md: 44, lg: 50 },
  space: { 1: 4, 2: 8, 3: 12, 4: 16, 5: 20 },
  text: { xs: 12, sm: 14, lg: 18 },
} as const;

/** The tokens for the device's current colour scheme. Wrap the app in your own provider if you manage the theme yourself. */
export function useTokens(): ManicatTokens {
  return useColorScheme() === "dark" ? darkTokens : lightTokens;
}

/**
 * Date helpers shared by the calendar, date picker and date range picker ports (React Native and Vue). Pure functions on
 * `Date`, no dependency: a month is always laid out as six weeks so the grid never changes height between months.
 */

export type CalendarDateMatcher = (date: Date) => boolean;

export interface CalendarLimits {
  minDate?: Date;
  maxDate?: Date;
  disabledDates?: CalendarDateMatcher;
}

export const startOfDay = (date: Date) => new Date(date.getFullYear(), date.getMonth(), date.getDate());
export const startOfMonth = (date: Date) => new Date(date.getFullYear(), date.getMonth(), 1);
export const addMonths = (date: Date, count: number) => new Date(date.getFullYear(), date.getMonth() + count, 1);
export const addDays = (date: Date, count: number) => new Date(date.getFullYear(), date.getMonth(), date.getDate() + count);

export const sameDay = (a?: Date | null, b?: Date | null) =>
  Boolean(a && b) && a!.getFullYear() === b!.getFullYear() && a!.getMonth() === b!.getMonth() && a!.getDate() === b!.getDate();

/** The 42 days shown for a month, starting on `weekStartsOn` (0 is Sunday, 1 is Monday). */
export function monthGrid(month: Date, weekStartsOn: 0 | 1 = 0): Date[] {
  const first = startOfMonth(month);
  const offset = (first.getDay() - weekStartsOn + 7) % 7;
  return Array.from({ length: 42 }, (_, index) => addDays(first, index - offset));
}

/** Short weekday names in column order, in the given locale. */
export function weekdayLabels(locale = "en-US", weekStartsOn: 0 | 1 = 0): string[] {
  // 2024-01-07 was a Sunday.
  return Array.from({ length: 7 }, (_, index) => new Date(2024, 0, 7 + ((index + weekStartsOn) % 7)).toLocaleDateString(locale, { weekday: "short" }));
}

export const monthLabel = (month: Date, locale = "en-US") => month.toLocaleDateString(locale, { month: "long", year: "numeric" });

export function isDisabled(date: Date, { minDate, maxDate, disabledDates }: CalendarLimits): boolean {
  const day = startOfDay(date).getTime();
  return Boolean((minDate && day < startOfDay(minDate).getTime()) || (maxDate && day > startOfDay(maxDate).getTime()) || disabledDates?.(date));
}
